    }

    // Second invocation should have been spawned (task2 still in_progress)
    expect(runSpy).toHaveBeenCalledTimes(2);

    await engine.stop();
  });

  // AC: @agent-dispatch-engine ac-17
  it("should discard queued entries when task has been deleted", async () => {
