    // Triggering changes after stop should be no-ops
    let enqueueCount = 0;
    vi.spyOn(engine as unknown as { _enqueue: (a: unknown, c: unknown) => void }, "_enqueue").mockImplementation(() => {
      enqueueCount++;
    });

