describe("AC-11: Graceful shutdown waits for active invocations", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-dispatch-ac11-");
  });

  afterEach(async () => {
    await cleanupTempDir(testDir);
  });

