 745→  /**
 746→   * Build a deduplication key for a state change.
 747→   * AC: @agent-dispatch-engine ac-7
 748→   */
 749→  private _dedupKey(change: TaskStateChange): DedupKey {
 750→    return `${change.taskId}:${change.fromStatus}:${change.toStatus}`;
 751→  }
 752→
 753→  /**
 754→   * Check whether this event is a duplicate within the dedup window.
 755→   * AC: @agent-dispatch-engine ac-7
 756→   */
 757→  private _isDuplicate(change: TaskStateChange): boolean {
 758→    const key = this._dedupKey(change);
 759→    const expiry = this.recentEvents.get(key);
 760→    if (expiry === undefined) return false;
 761→    return change.timestamp < expiry;
 762→  }
 763→
 764→  /**
 765→   * Record a state change for deduplication.
 766→   * AC: @agent-dispatch-engine ac-7
 767→   */
 768→  private _recordEvent(change: TaskStateChange): void {
 769→    const key = this._dedupKey(change);
 770→    this.recentEvents.set(key, change.timestamp + this.dedupWindowMs);
 771→
 772→    // Prune expired entries periodically
 773→    if (this.recentEvents.size > 1000) {
 774→      const now = Date.now();
 775→      for (const [k, expiry] of this.recentEvents) {
 776→        if (expiry < now) this.recentEvents.delete(k);
 777→      }
 778→    }
 779→  }
 780→
 781→  /**
 782→   * Enqueue a dispatch entry for an agent.
 783→   * AC: @agent-dispatch-engine ac-3
 784→   */
 785→  private _enqueue(agent: LoadedAgent, change: TaskStateChange): void {
 786→    const queue = this.queues.get(agent.id) ?? [];
 787→    const entry: QueueEntry = {
 788→      agent,
 789→      change,
 790→      retryCount: 0,
 791→      nextRetryAt: 0,
 792→      enqueuedAtMs: Date.now(),
 793→      sequence: this.nextQueueSequence++,
 794→    };
 795→    this._insertQueueEntry(queue, entry);
 796→    this.queues.set(agent.id, queue);
 797→  }
 798→
 799→  /**
 800→   * Insert an entry into an agent queue using deterministic status precedence.
 801→   * AC: @dispatch-in-progress-priority ac-1
 802→   */
 803→  private _insertQueueEntry(queue: QueueEntry[], entry: QueueEntry): void {
 804→    const insertAt = queue.findIndex((queued) => this._compareQueueEntries(entry, queued) < 0);
 805→    if (insertAt === -1) {
 806→      queue.push(entry);
 807→      return;
 808→    }
 809→    queue.splice(insertAt, 0, entry);
 810→  }
 811→
 812→  /**
 813→   * Compare queue entries by dispatch precedence, then by enqueue sequence.
 814→   * AC: @dispatch-in-progress-priority ac-1
 815→   */
 816→  private _compareQueueEntries(a: QueueEntry, b: QueueEntry): number {
 817→    const statusDelta = STATUS_PRECEDENCE[a.change.toStatus] - STATUS_PRECEDENCE[b.change.toStatus];
 818→    if (statusDelta !== 0) return statusDelta;
 819→    return a.sequence - b.sequence;
 820→  }
 821→
 822→  /**
 823→   * Drain queues, spawning invocations up to each agent's max_concurrent limit.
 824→   * AC: @agent-dispatch-engine ac-3, ac-17
 825→   */
 826→  private async _drainQueues(agents: LoadedAgent[]): Promise<void> {
 827→    // Prevent new invocation starts during/after shutdown.
 828→    if (!this.running) return;
 829→
 830→    // AC: @agent-dispatch-engine ac-17 - Load current task states once for staleness checks
 831→    let currentTaskStates: Map<string, TaskStatus> | undefined;
 832→    try {
 833→      const ctx = await initContext(this.projectDir);
 834→      const tasks = await loadAllTasks(ctx);
 835→      currentTaskStates = new Map(
 836→        tasks.map((t) => [t._ulid, t.status as TaskStatus]),
 837→      );
 838→    } catch {
 839→      // If we can't load tasks, skip staleness checks (best effort)
 840→    }
 841→
 842→    for (const agent of agents) {
 843→      const maxConcurrent = agent.concurrency?.max_concurrent ?? 1;
 844→      const active = this.activeCount.get(agent.id) ?? 0;
 845→      const queue = this.queues.get(agent.id) ?? [];
 846→
 847→      // AC: @agent-dispatch-engine ac-17 - Discard stale entries before spawning.
 848→      // Only discard when we have positive evidence the task moved: either the task
 849→      // exists on disk with a different status, or the task was previously tracked
 850→      // (in prevTaskStates) but is no longer found (deleted).
 851→      if (currentTaskStates) {
 852→        const before = queue.length;
 853→        for (let i = queue.length - 1; i >= 0; i--) {
 854→          const entry = queue[i];
 855→          const currentStatus = currentTaskStates.get(entry.change.taskId);
 856→          const expectedEvent = STATUS_TO_EVENT[entry.change.toStatus];
 857→          if (!expectedEvent) continue; // No event mapping — skip check
 858→          if (currentStatus === undefined) {
 859→            // Task not on disk — only discard if we previously knew about it
 860→            // (it was deleted). Tasks from pure handleStateChange events without
 861→            // on-disk presence should still be processed.
 862→            if (this.prevTaskStates.has(entry.change.taskId)) {
 863→              queue.splice(i, 1);
 864→            }
 865→          } else {
 866→            const currentEvent = STATUS_TO_EVENT[currentStatus];
 867→            if (currentEvent !== expectedEvent) {
 868→              queue.splice(i, 1);
 869→            }
 870→          }
 871→        }
 872→        if (before > queue.length) {
 873→          console.log(
 874→            `[dispatch] Discarded ${before - queue.length} stale queue entries for agent "${agent.id}"`,
 875→          );
 876→        }
 877→      }
 878→
 879→      let slots = maxConcurrent - active;
 880→      while (slots > 0 && queue.length > 0) {
 881→        const now = Date.now();
 882→        const nextReadyIndex = queue.findIndex((entry) => entry.nextRetryAt <= now);
 883→        if (nextReadyIndex === -1) {
 884→          break;
 885→        }
 886→        const [entry] = queue.splice(nextReadyIndex, 1);
 887→        const spawned = this._spawnInvocation(agent, entry);
 888→        if (spawned) slots--;
 889→      }
 890→
 891→      this.queues.set(agent.id, queue);
 892→    }
 893→  }
 894→
 895→  /**
 896→   * Build dispatch-mode prompt guardrails to keep autonomous agents from
 897→   * stopping with handoff text instead of performing required actions.
 898→   *
 899→   * AC: @agent-dispatch-engine ac-13, ac-14, ac-15, ac-16
 900→   */
 901→  private _buildDispatchPrompt(agent: LoadedAgent, change: TaskStateChange): string {
 902→    const trigger = (STATUS_TO_EVENT[change.toStatus] ?? "task.ready") as SessionTrigger;
 903→    const taskRef = change.taskRef;
 904→
 905→    // AC: @agent-dispatch-engine ac-16 - Interpolate prompt_template variables
 906→    const templateVars: Record<string, string> = {
 907→      task_ref: taskRef,
 908→      task_title: change.task?.title ?? "(unavailable)",
 909→      trigger,
 910→      review_url: change.task?.review_url ?? "",
 911→    };
 912→    const rawTemplate = agent.prompt_template ?? `Work on task ${taskRef}`;
 913→    const basePrompt = interpolateTemplate(rawTemplate, templateVars);
 914→
 915→    // AC: @agent-dispatch-engine ac-13 - Orientation context
 916→    const orientation = buildOrientationContext(taskRef, trigger, change.task);
 917→
 918→    const autonomousPreamble = [
 919→      "AUTONOMOUS DISPATCH MODE (no interactive user is available).",
 920→      "- Do not ask for confirmation, approval, or next-step handoff.",
 921→      "- Execute required commands directly in this invocation.",
 922→      "- Do not end your turn with a recommendations-only summary. Perform the next required action yourself.",
 923→      "- Do not end your turn until the expected task transition is complete, or you have explicitly blocked the task with `kspec task block <task> --reason \"...\"`.",
 924→      "- If you find an open PR/branch from a different task, create or switch to a dedicated branch for this task before committing to avoid PR conflation.",
 925→    ];
 926→
 927→    const triggerSpecific =
 928→      trigger === "task.pending_review"
 929→        ? [
 930→            `Review flow completion criteria for ${taskRef}:`,
 931→            "- Execute your configured review workflow directly (no handoff).",
 932→            `- If blocking issues are found, transition ${taskRef} out of pending_review appropriately (for example needs_work).`,
 933→            `- If review gates are clean, perform your workflow's completion actions directly in this invocation.`,
 934→          ]
 935→        : [
 936→            `Work flow completion criteria for ${taskRef}:`,
 937→            "- Execute your configured work workflow directly (no handoff).",
 938→            `- Perform the required commands to move ${taskRef} to the next appropriate state in this same invocation.`,
 939→            "- If your workflow includes git or PR steps, execute them directly instead of deferring to a human.",
 940→          ];
 941→
 942→    return `${basePrompt}\n\n${orientation}\n\n${autonomousPreamble.join("\n")}\n\n${triggerSpecific.join("\n")}`;
 943→  }
 944→
 945→  /**
 946→   * Spawn a single invocation for a queue entry.
 947→   * Returns true if an invocation was actually started, false if skipped.
 948→   * AC: @agent-dispatch-engine ac-9, ac-10, ac-11, ac-12
 949→   */
 950→  private _spawnInvocation(agent: LoadedAgent, entry: QueueEntry): boolean {
 951→    const agentId = agent.id;
 952→
 953→    // Increment active count
 954→    this.activeCount.set(agentId, (this.activeCount.get(agentId) ?? 0) + 1);
 955→
 956→    // AC: @agent-dispatch-engine ac-10 - Check adapter resolvability before spawn
 957→    const adapterId = agent.adapter ?? "claude-agent-acp";
 958→    const adapter = getAdapter(adapterId);
 959→    if (!adapter) {
 960→      console.error(
 961→        `[dispatch] Cannot resolve adapter "${adapterId}" for agent "${agentId}". Skipping invocation.`,
 962→      );
 963→      // Decrement active count since we're not actually running
 964→      const currentActive = this.activeCount.get(agentId) ?? 1;
 965→      this.activeCount.set(agentId, Math.max(0, currentActive - 1));
 966→      // AC: @agent-dispatch-engine ac-10 - Add task note for unresolvable adapter
 967→      if (this.kspecCliPath) {
 968→        spawnSync(process.execPath, [
 969→          this.kspecCliPath,
 970→          "task", "note", entry.change.taskRef,
 971→          `[AGENT-SKIP] Cannot resolve adapter "${adapterId}" for agent "${agentId}". Invocation skipped.`,
 972→        ], { cwd: this.cwd });
 973→      }
 974→      return false;
 975→    }
 976→
 977→    // AC: @agent-dispatch-engine ac-11 - Create abort controller for graceful cancellation
 978→    const abortController = new AbortController();
 979→    this.invocationAbortControllers.add(abortController);
 980→
 981→    // AC: @cli-agent-commands ac-6 - Pre-assign session ID for status tracking
 982→    const preSessionId = ulid();
 983→    const invocationId = ulid();
 984→    const trackingRecord: ActiveInvocationRecord = {
 985→      invocationId,
 986→      sessionId: preSessionId,
 987→      agentId,
 988→      agentName: agent.name,
 989→      taskRef: entry.change.taskRef,
 990→      startedAtMs: Date.now(),
 991→    };
 992→    this.activeInvocationDetails.set(invocationId, trackingRecord);
 993→
 994→    // AC: @daemon-agent-dispatch ac-3, ac-4 - Emit started event
 995→    this.onInvocationEvent?.({
 996→      type: "started",
 997→      session_id: preSessionId,
 998→      agent_id: agentId,
 999→      task_id: entry.change.taskRef,
1000→      status: "started",
1001→      timestamp: Date.now(),
1002→    });
1003→
1004→    // AC: @cli-agent-commands ac-13, @daemon-agent-dispatch ac-8 - stream text chunks to watchers
1005→    const taskId = entry.change.taskRef ?? null;
1006→    const onUpdate = this.onTextChunk
1007→      ? (update: import("../acp/index.js").SessionUpdate) => {
1008→          if (
1009→            update.sessionUpdate === "agent_message_chunk" &&
1010→            update.content.type === "text"
1011→          ) {
1012→            this.onTextChunk!(preSessionId, agentId, taskId, update.content.text);
1013→            return;
1014→          }
1015→          // Non-text updates (especially tool events) delimit logical message runs.
1016→          // Emit an empty sentinel so watch renderers can end the current line
1017→          // without needing to infer boundaries from prose punctuation.
1018→          this.onTextChunk!(preSessionId, agentId, taskId, "");
1019→        }
1020→      : undefined;
1021→
1022→    const options: InvocationOptions = {
1023→      agent,
1024→      specDir: this.specDir,
1025→      cwd: this.cwd,
1026→      taskRef: entry.change.taskRef,
1027→      prompt: this._buildDispatchPrompt(agent, entry.change),
1028→      trigger: (STATUS_TO_EVENT[entry.change.toStatus] ?? "task.ready") as SessionTrigger,
1029→      kspecCliPath: this.kspecCliPath,
1030→      abortSignal: abortController.signal,
1031→      sessionId: preSessionId,
1032→      onUpdate,
1033→    };
1034→
1035→    // AC: @agent-dispatch-engine ac-12 - Wrap invocation in shadow mutex
1036→    const invocationPromise = this.shadowMutex
1037→      .runExclusive(async () => {
1038→        // AC: @agent-dispatch-engine ac-9 - Retry on transient errors
1039→        try {
1040→          await runInvocation(options);
1041→          // Reset retry count on success
1042→          entry.retryCount = 0;
1043→          // AC: @daemon-agent-dispatch ac-3, ac-4 - Emit completed event
1044→          this.onInvocationEvent?.({
1045→            type: "completed",
1046→            session_id: preSessionId,
1047→            agent_id: agentId,
1048→            task_id: entry.change.taskRef,
1049→            status: "completed",
1050→            timestamp: Date.now(),
1051→          });
1052→        } catch (err) {
1053→          const retryLimit = agent.budget?.max_retries ?? 3;
1054→          if (entry.retryCount < retryLimit) {
1055→            entry.retryCount++;
1056→            const backoffMs = Math.min(
1057→              1000 * Math.pow(2, entry.retryCount - 1),
1058→              30_000,
1059→            );
1060→            entry.nextRetryAt = Date.now() + backoffMs;
1061→            console.warn(
1062→              `[dispatch] Invocation for agent "${agentId}" failed (attempt ${entry.retryCount}/${retryLimit}), retrying in ${backoffMs}ms`,
1063→              err,
1064→            );
1065→            // Re-enqueue for retry while preserving status precedence ordering.
1066→            const queue = this.queues.get(agentId) ?? [];
1067→            this._insertQueueEntry(queue, entry);
1068→            this.queues.set(agentId, queue);
1069→            // AC: @agent-dispatch-engine ac-9 - Schedule wake-up to drain retry
1070→            setTimeout(() => {
1071→              if (this.running) {
1072→                this._loadAgents()
1073→                  .then((agents) => this._drainQueues(agents))
1074→                  .catch(() => {/* best effort */});
1075→              }
1076→            }, backoffMs);
1077→          } else {
1078→            console.error(
1079→              `[dispatch] Agent "${agentId}" exceeded retry limit. Dropping invocation.`,
1080→              err,
1081→            );
1082→            // AC: @daemon-agent-dispatch ac-3, ac-4 - Emit failed event when retry limit exceeded
1083→            this.onInvocationEvent?.({
1084→              type: "failed",
1085→              session_id: preSessionId,
1086→              agent_id: agentId,
1087→              task_id: entry.change.taskRef,
1088→              status: "failed",
1089→              timestamp: Date.now(),
1090→            });
1091→          }
1092→        }
1093→      })
1094→      .then(async () => {
1095→        // Decrement active count and drain again
1096→        const currentActive = this.activeCount.get(agentId) ?? 1;
1097→        this.activeCount.set(agentId, Math.max(0, currentActive - 1));
1098→
1099→        if (!this.running) return;
1100→
