    try {
      const engine = new DispatchEngine({ projectDir: testDir, specDir: testDir, kspecCliPath: MOCK_KSPEC_CLI });

      type EngineInternal = { _spawnInvocation: (a: unknown, e: unknown) => void };
      const taskRef = `@${testUlid("TASK")}`;
