      const entry = { agent: agentBadAdapter, change, retryCount: 0, nextRetryAt: 0 };

      vi.spyOn(console, "error").mockImplementation(() => {});
      (engine as unknown as EngineInternal)._spawnInvocation(agentBadAdapter, entry);
