      enqueueCount++;
    });

    await engine.start();
    enqueueCount = 0;

    await writeTasks(testDir, [
      { _ulid: taskId, status: "pending", automation: "eligible" },
    ]);

    await engine.handleFileChange(testDir);

    expect(enqueueCount).toBe(1);

    await engine.stop();
