    const firstBlock = new Promise<void>((r) => { resolveFirst = r; });
    const runSpy = vi.spyOn(invocationModule, "runInvocation")
      .mockImplementationOnce(async () => {
        await firstBlock;
        return { session: {} as any, outcome: "success" as const, durationMs: 1 };
