// ─── AC-5: File watcher diffs task states ────────────────────────────────────

// AC: @agent-dispatch-engine ac-5
describe("AC-5: File watcher diffs task states", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-dispatch-ac5-");
  });

  afterEach(async () => {
    await cleanupTempDir(testDir);
