    vi.spyOn(engine, "handleStateChange").mockImplementation(async (change) => {
      detectedChanges.push(change);
    });

    await engine.handleFileChange(testDir);

    expect(detectedChanges).toHaveLength(0);

    await engine.stop();
  });
});

