// ─── AC-7: Event deduplication ───────────────────────────────────────────────

// AC: @agent-dispatch-engine ac-7
describe("AC-7: Event deduplication within time window", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-dispatch-ac7-");
  });

  afterEach(async () => {
