    for (let i = 0; i < 50 && runSpy.mock.calls.length === 0; i++) {
      await new Promise((r) => setTimeout(r, 5));
    }
    expect(runSpy).toHaveBeenCalledTimes(1);

    // Enqueue another event while first is running
