// AC: @agent-dispatch-engine ac-12
describe("AC-12: Shadow branch mutations serialized via mutex", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-dispatch-ac12-");
  });

  afterEach(async () => {
