    await new Promise((r) => setTimeout(r, 250));

    expect(reconcileSpy.mock.calls.length).toBeGreaterThanOrEqual(1);

    await engine.stop();
  });

  // AC: @agent-dispatch-engine ac-20
  it("should NOT run reconciliation when interval is 0", async () => {
